package com.bank.springgrpc.service;

import com.bank.springgrpc.gen.*;
import io.grpc.stub.StreamObserver;
import net.devh.boot.grpc.server.service.GrpcService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.math.BigDecimal;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

// @GrpcService auto-registers this bean with the embedded gRPC server. No boilerplate.
@GrpcService
public class TransferGrpcService extends TransferServiceGrpc.TransferServiceImplBase {
    private static final Logger log = LoggerFactory.getLogger(TransferGrpcService.class);
    private final Map<String, BigDecimal> balances = new ConcurrentHashMap<>(Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000")));    // Priya

    @Override
    public void transfer(TransferRequest req, StreamObserver<TransferResponse> obs) {
        BigDecimal amount = new BigDecimal(req.getAmount());
        log.info("Transfer Rs.{} {}->{}", amount, req.getFromAccount(), req.getToAccount());
        balances.put(req.getFromAccount(), balances.get(req.getFromAccount()).subtract(amount));
        balances.merge(req.getToAccount(), amount, BigDecimal::add);
        obs.onNext(TransferResponse.newBuilder()
            .setTransferId("TXF-" + UUID.randomUUID()).setStatus("COMPLETED").build());
        obs.onCompleted();
    }
}
