package com.bank.springgrpc.health;

import io.grpc.protobuf.services.HealthStatusManager;
import io.grpc.health.v1.HealthCheckResponse.ServingStatus;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import jakarta.annotation.PostConstruct;

// Tie gRPC health status to REAL readiness (e.g. DB pool warmed). K8s probes this.
@Component
public class ReadinessHealthIndicator {
    private static final Logger log = LoggerFactory.getLogger(ReadinessHealthIndicator.class);
    private final HealthStatusManager healthManager;

    public ReadinessHealthIndicator(HealthStatusManager healthManager) {
        this.healthManager = healthManager;
    }

    @PostConstruct
    public void markServingWhenReady() {
        // Report NOT_SERVING until dependencies (DB pool) are ready, then SERVING.
        healthManager.setStatus("", ServingStatus.NOT_SERVING);
        boolean dbReady = warmUpDatabasePool();
        healthManager.setStatus("", dbReady ? ServingStatus.SERVING : ServingStatus.NOT_SERVING);
        log.info("gRPC health set to {}", dbReady ? "SERVING" : "NOT_SERVING");
    }

    private boolean warmUpDatabasePool() { return true; }   // real check in production
}
